(195, 'Tim', 'tim.bestfloors@protonmail.com', '01213508384', 'Hello there,\n\nThis is Tim from Best Floors.\nWe are based in the UK.\n\nI came across your website while researching SPC importing.\nDo you export SPC?\n\nIf yes please send me the catalog along with the price list.\n\nThanks in advance', '2023-11-09 01:02:41', '2023-11-09 01:02:41'),
(196, 'Mrs Manisha Sharma', 'offshore.infrastructureslimited@offshorelnfra.com', '918514433000', 'Dear Sir/Madam, \nGood day – I am reaching out to you on behalf of Offshore infrastructures Limited India.\n\nWe would like to register your Company as a supplier, vendor and intending partners in Offshore infrastructures Limited 2023/2024 projects procurement systems here in India.\n\nThese projects are open for all companies around the world, if you have intention to participate in the process, please confirm your interest by asking for Vendor Questionnaire and EOI.\n\nWe appreciate your interest in this invitation and look forward to your early response though our official email:\n\nKind Regards,\n\nMrs Manisha Sharma\nChief procurement officer\nOffshore infrastructures Limited\nAddress: 22,Udyog Kshetra,Mulund Link Road,\nMumbai-400 080- INDIA\nEmail: offshore.infrastructureslimited@offshorelnfra.com', '2023-11-12 03:14:12', '2023-11-12 03:14:12'),
(197, 'Joseph DeFries', 'joe@usconstructionconsultants.com', '9547783192', 'Hi\nDo you manufacture 2cm x 60 x 60cm, 2cm x 60 x 120cm or what other sizes?\nAnd what is your Price FOB Mundra\nand where on your website do I see these 2cm(20mm) tile\nAnd can you send me a price list of all your other tile products\nThanks so much\n\n-- \nJoe DeFries\nManufacturers Rep\nPresident\nUS Construction Consultants\n4613 N University Dr. unit 331\nCoral Springs, FL USA 33067\noffice 1-800-590-1980\nCell 954-778-3192 WhatsApp\n\nWarehouse/Showroom\n110 NE 179th Street\nMiami, FL 33162', '2023-11-12 09:26:33', '2023-11-12 09:26:33'),
(198, 'Hashcrypt Technologies', 'contact@hashcrypt.com', '9106427611', 'Hello, \n\nAt Hashcrypt Technologies, we\'re not just in the business of web design, web development, and software development; we\'re in the business of turning dreams into digital realities.\n\nWhy Choose Us?\n-> Creative flair meets technical expertise.\n-> Timely delivery without compromising quality.\n-> Your vision, our mission.\n\nContact us at https://hashcrypt.com/contact or visit hashcrypt.com for a glimpse of what we can create together.', '2023-11-18 01:54:04', '2023-11-18 01:54:04'),
(199, 'Sneha Sharma', 'info@grmceramics.in', '9712956250', 'Namastey,\n\nWith a legacy spanning decades, we at GRM Ceramics have our expertise in Zinc Oxide, Zirconium, Special Clays, and an extensive array of ceramics materials. \nOur commitment to excellence in the ceramics industry stands as a testament to our unwavering dedication.\n\nWe proudly lead the way as:\n\nPremier Frit Manufacturers\nSpecialized Customized Compound Manufacturers\nReliable Raw Material Suppliers\n\nWe are passionate about fostering collaborations that drive innovation and success. Your inquiries, ideas, and partnership proposals are welcomed at info@grmceramics.in. We eagerly anticipate the opportunity to connect with you and provide our unparalleled services.\n\nLooking forward to the prospect of serving you,\n\nBest Regards,\nMs. Sneha Sharma\nMarketing Executive', '2023-11-25 05:04:18', '2023-11-25 05:04:18'),
