INSERT INTO `faqs` (`id`, `question`, `answer`, `schema`, `is_spc`, `is_quartz`, `created_at`, `updated_at`) VALUES
(1, 'What are quartz countertops?', 'Quartz countertops are elegant, practical, and low-maintenance, made from natural quartz stone with resin.', NULL, 0, 1, '2026-06-16 11:18:59', '2026-06-16 11:18:59'),
(2, 'What are the advantages of quartz slabs?', 'Attractive appearance, ease of maintenance, variety of options, cost-effectiveness, and durability.', NULL, 0, 1, '2026-06-16 11:19:45', '2026-06-16 11:19:45'),
(3, 'What are the disadvantages of quartz slabs?', 'Quartz is not heat-resistant and can be more expensive than some other countertop materials like granite.', NULL, 0, 1, '2026-06-16 11:20:28', '2026-06-17 11:07:24'),
(4, 'How can quartz slabs be used?', 'Quartz slabs are used for countertops, backsplashes, tabletops, and even flooring in kitchens and bathrooms.', NULL, 0, 1, '2026-06-16 11:23:48', '2026-06-16 11:23:48'),
(5, 'Are quartz slabs high maintenance?', 'Quartz slabs are low-maintenance and easy to clean with mild soap and water. They do not require sealing like granite.', NULL, 0, 1, '2026-06-16 11:24:16', '2026-06-16 11:24:16'),
(6, 'How much is a slab of quartz?', 'The price of a quartz slab can vary, but on average it ranges from $50 to $100 per square foot, depending on the brand and quality.', NULL, 0, 1, '2026-06-16 11:25:24', '2026-06-16 11:25:24'),
(7, 'Do quartz countertops scratch easily?', 'Quartz countertops are highly scratch-resistant due to their hard surface, but they can still get scratched with excessive force.', NULL, 0, 1, '2026-06-16 11:26:19', '2026-06-16 11:26:19'),
(8, 'Is quartz more expensive than granite?', 'Quartz is generally more expensive than granite, though the cost can vary depending on quality and brand.', NULL, 0, 1, '2026-06-16 11:26:50', '2026-06-16 11:39:36'),
(9, 'Is quartz better than granite?', 'Quartz is engineered and more consistent in color and pattern, whereas granite is a natural stone with unique patterns.', NULL, 0, 1, '2026-06-16 11:28:03', '2026-06-16 11:28:03'),
(10, 'Does quartz stain easily?', 'Quartz is highly stain-resistant, but it\'s still important to clean up spills immediately, especially for acidic substances.', NULL, 0, 1, '2026-06-16 11:28:28', '2026-06-16 11:28:28'),
(11, 'Is quartz cheaper than concrete?', 'Quartz countertops can be more expensive than concrete, depending on the quality, but offer more durability and variety in design.', NULL, 0, 1, '2026-06-16 11:28:58', '2026-06-16 11:28:58'),
(12, 'Is quartz cheaper than marble?', 'Yes, quartz is generally more affordable than marble, which tends to be more expensive due to its natural stone origin.', NULL, 0, 1, '2026-06-16 11:29:27', '2026-06-16 11:29:27'),
(13, 'How should quartz be cleaned?', 'Clean quartz surfaces with warm water and a mild detergent. Avoid harsh chemicals or abrasive materials.', NULL, 0, 1, '2026-06-16 11:29:58', '2026-06-16 11:30:10'),
(16, 'What is SPC flooring?', 'SPC (Stone Plastic Composite) flooring is a rigid core vinyl flooring made from limestone powder, PVC, and stabilizers. It is highly durable, waterproof, and suitable for both residential and commercial spaces.', NULL, 1, 0, '2026-06-18 10:11:55', '2026-06-18 10:11:55'),
(17, 'Is SPC flooring waterproof?', 'Yes, SPC flooring is 100% waterproof, making it an excellent choice for kitchens, bathrooms, laundry rooms, and other moisture-prone areas.', NULL, 1, 0, '2026-06-18 10:13:20', '2026-06-18 10:13:20'),
(18, 'How durable is SPC flooring?', 'SPC flooring is highly durable and resistant to scratches, dents, stains, and daily wear, making it suitable for high-traffic areas.', NULL, 1, 0, '2026-06-18 10:22:14', '2026-06-18 10:22:29'),
(19, 'Can SPC flooring be installed over existing floors?', 'Yes, SPC flooring can often be installed over existing tile, concrete, vinyl, or hardwood floors, provided the surface is clean, dry, and level.', NULL, 1, 0, '2026-06-18 10:23:08', '2026-06-18 10:23:08'),
(20, 'Is SPC flooring eco-friendly?', 'Many SPC flooring products are manufactured using recyclable materials and are designed to meet environmental and indoor air quality standards.', NULL, 1, 0, '2026-06-18 10:34:21', '2026-06-18 10:34:21'),
(21, 'How long does SPC flooring last?', 'With proper installation and maintenance, high-quality SPC flooring can last 15 to 25 years or even longer in residential and commercial applications.', NULL, 1, 0, '2026-06-18 10:34:46', '2026-06-18 10:34:46'),
(22, 'Can SPC flooring be used with underfloor heating?', 'Most SPC flooring products are compatible with underfloor heating systems. Always follow the manufacturer\'s installation guidelines and temperature recommendations.', NULL, 1, 0, '2026-06-18 10:35:11', '2026-06-18 10:35:11'),
(23, 'Does SPC flooring require underlayment?', 'Many SPC flooring products come with an attached underlayment, but additional underlayment may be recommended depending on the subfloor condition and installation requirements.', NULL, 1, 0, '2026-06-18 10:35:56', '2026-06-18 10:35:56');
