INSERT INTO `testimonials` (`id`, `client_name`, `company_name`, `designation`, `testimonial`, `client_image`, `rating`, `location`, `project_name`, `product_type`, `status`, `display_order`, `created_at`, `updated_at`) VALUES
(11, 'The DeadZone', NULL, NULL, '<p>Value for money! Affordable without compromising on style or strength. Their quartz slabs are stunning and unique.</p>', 'deadzone.png', 4, NULL, NULL, 'Quartz surface', 'active', 1, '2026-06-17 01:31:41', '2026-06-25 05:15:13'),
(12, 'Sanjay Mehta', NULL, NULL, 'Very good display for 600*300', NULL, 5, NULL, NULL, 'SPC Flooring', 'active', 2, '2026-06-17 07:21:28', '2026-06-17 09:27:59'),
(13, 'Yogesh Kharat', NULL, NULL, 'Manufacturing and supply of ceramic tile', 'yogesh.png', 4, NULL, NULL, 'Quartz surface', 'active', 0, '2026-06-17 07:24:52', '2026-06-17 09:26:54'),
(14, 'Vishva Jamnapara', NULL, NULL, '<p>Top-notch SPC tile collection. Trendy designs and eco-friendly materials. Great for homes and retail spaces alike.</p>', NULL, 5, NULL, NULL, 'SPC Flooring', 'active', 0, '2026-06-17 07:31:00', '2026-06-26 07:21:27'),
(15, 'Arshad Sipai', NULL, NULL, '<p>Their slabs are beautifully crafted and perfect for kitchen tops and vanities. Unique patterns too.</p>', 'i1.png', 4, NULL, NULL, 'Quartz surface', 'active', 0, '2026-06-17 07:38:31', '2026-06-25 06:25:22'),
(20, 'Sandeep Vamja', NULL, NULL, '<p>Great SPC flooring quality from Argile Group. The product is durable, stylish, and easy to install. Very satisfied with the finish and overall service!</p>', 'sandeep.png', 5, NULL, NULL, 'SPC Flooring', 'active', 0, '2026-06-25 05:19:41', '2026-06-25 05:46:56'),
(21, 'Avni Varneshiya', NULL, NULL, '<p>Professional team and on-time delivery.<br>Their quartz surfaces transformed our kitchen countertops. Elegant look and solid build. Will definitely recommend to others!</p>', '1782368705_avni.png', 5, NULL, NULL, 'Quartz surface', 'active', 0, '2026-06-25 05:45:57', '2026-06-25 06:25:05'),
(22, 'Jignesh Rathod', NULL, NULL, '<p>Reliable supplier for quality tiles.<br>The Product we ordered were well-packed, polished, and ready to install. Truly premium quality.</p><p>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p>', '', 5, NULL, NULL, 'SPC Flooring', 'active', 0, '2026-06-25 05:52:31', '2026-06-25 06:24:19');
